sys_ws_operation.operation_script:
(function process(request, response) {
  try {
    var body = request.body.data;

    // Validate required fields
    var errors = {};
    if (!body.external_id) {
      errors.external_id = 'external_id is required';
    }
    if (!body.asset_tag) {
      errors.asset_tag = 'asset_tag is required';
    }
    if (!body.serial_number) {
      errors.serial_number = 'serial_number is required';
    }

    if (Object.keys(errors).length > 0) {
      response.setStatus(400);
      response.setBody({ error: 'Validation failed', fields: errors });
      return;
    }

    // Look up existing asset by asset_tag OR serial_number
    var gr = new GlideRecord('x_848842_techdesk_asset');
    gr.addEncodedQuery('asset_tag=' + body.asset_tag + '^ORserial_number=' + body.serial_number);
    gr.query();

    if (gr.next()) {
      // Update existing record
      gr.setValue('serial_number', body.serial_number);
      if (body.lifecycle_state) {
        gr.setValue('lifecycle_state', body.lifecycle_state);
      }
      gr.setValue('last_audit_date', new GlideDateTime().toString());
      gr.update();

      response.setStatus(200);
      response.setBody({
        status: 'updated',
        sys_id: gr.getUniqueValue(),
        asset_tag: gr.getValue('asset_tag')
      });
    } else {
      // Create new record
      var newGr = new GlideRecord('x_848842_techdesk_asset');
      newGr.initialize();
      newGr.setValue('asset_tag', body.asset_tag);
      newGr.setValue('serial_number', body.serial_number);
      if (body.external_id) {
        newGr.setValue('external_id', body.external_id);
      }
      if (body.display_name) {
        newGr.setValue('display_name', body.display_name);
      }
      if (body.asset_type) {
        newGr.setValue('asset_type', body.asset_type);
      }
      if (body.lifecycle_state) {
        newGr.setValue('lifecycle_state', body.lifecycle_state);
      }
      if (body.assigned_to) {
        newGr.setValue('assigned_to', body.assigned_to);
      }
      if (body.location) {
        newGr.setValue('location', body.location);
      }
      if (body.purchase_date) {
        newGr.setValue('purchase_date', body.purchase_date);
      }
      if (body.warranty_expiry) {
        newGr.setValue('warranty_expiry', body.warranty_expiry);
      }
      newGr.setValue('last_audit_date', new GlideDateTime().toString());
      var sysId = newGr.insert();

      response.setStatus(201);
      response.setBody({
        status: 'created',
        sys_id: sysId,
        asset_tag: body.asset_tag
      });
    }
  } catch (e) {
    gs.error('TechDesk CMDB Sync Asset error: ' + e.message);
    response.setStatus(500);
    response.setBody({ error: 'Internal server error', message: e.message });
  }
})(request, response);
